import re,os
tot=0; files={}
for root,d,fs in os.walk('AlgebraicJacobian'):
    for f in fs:
        if f.endswith('.lean'):
            p=os.path.join(root,f)
            src=open(p).read()
            # strip block comments /- -/ and line comments --
            src2=re.sub(r'/-.*?-/', '', src, flags=re.S)
            src2=re.sub(r'--[^\n]*', '', src2)
            n=len(re.findall(r'\bsorry\b', src2))
            if n: files[p]=n; tot+=n
print(tot, len(files))
for k,v in sorted(files.items()): print(v,k)
EOF

